use vstd::prelude::*;

verus! {

  /// Reverse in‐place the prefix s[0..k] of a Vec<i32>.
  ///
  /// Requires  2 ≤ k ≤ s.len().
  /// Ensures
  ///   • the overall length is unchanged,
  ///   • for all i<k, after the call s[i] == old(s)[k−1−i], 
  ///   • for all i≥k, s[i] == old(s)[i].
  fn reverse_upto_k(s: &mut Vec<i32>, k: usize)
    requires
      2 <= k && k <= s.len(),
    ensures
      s.len() == old(s).len(),
      forall |i: usize| i < k ==> s.view()[i] == old(s.view())[k - 1 - i],
      forall |i: usize| k <= i && i < s.len() ==> s.view()[i] == old(s.view())[i],
  {
    // Take a ghost snapshot of the original contents
    let old_s: Seq<i32> = s.view();

    // We'll swap pairs (left, k−1−left), for left = 0 .. half−1
    let mut left: usize = 0;
    let half: usize = k / 2;

    while left < half
      invariant
        left <= half,
        // length never changes
        s.len() == old_s.len(),

        // every j < left has been swapped:
        //   s[j]       == old_s[k−1−j]
        //   s[k−1−j]   == old_s[j]
        forall |j: usize|
          j < left ==>
            s.view()[j] == old_s[k - 1 - j]
            && s.view()[k - 1 - j] == old_s[j],

        // the “middle” of the prefix, j in [left, k−left), is still the same
        forall |j: usize|
          left <= j && j < k - left ==>
            s.view()[j] == old_s[j],

        // the suffix from k onward is untouched
        forall |j: usize|
          k <= j && j < s.len() ==>
            s.view()[j] == old_s[j],
      decreases
        half - left,
    {
      let right = k - 1 - left;
      let tmp: i32 = s[left];
      s[left] = s[right];
      s[right] = tmp;
      left += 1;
    }
  }
}

